USE `if0_43478740_3a1`;

-- La consigna pedia UNIQUE(club, anio); hay planteles Metro+Nacional
-- del mismo club y anio (Estudiantes 1982 / 1982 Nacional, etc.).
-- Se pasa a UNIQUE(club, etiqueta). Solo para bases creadas antes.
CREATE TABLE IF NOT EXISTS `logros` (`id` INT AUTO_INCREMENT PRIMARY KEY, `partida_id` INT NOT NULL, `codigo` VARCHAR(40) NOT NULL, `fecha` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY `uq_logro` (`partida_id`, `codigo`), FOREIGN KEY (`partida_id`) REFERENCES `partidas`(`id`));

-- Clubes (nombres tal cual el doc; Boca corto se unifica abajo) --
-- Unificar Boca Juniors (base vieja) con Boca (doc) --
UPDATE IGNORE temporadas t JOIN clubes c_old ON c_old.id = t.club_id JOIN clubes c_new ON c_new.nombre = 'Boca' SET t.club_id = c_new.id WHERE c_old.nombre = 'Boca Juniors';
DELETE FROM clubes WHERE nombre = 'Boca Juniors' AND NOT EXISTS (SELECT 1 FROM temporadas WHERE temporadas.club_id = clubes.id);

